import{_ as e,o,c as l,aw as t}from"./chunks/framework.DLufY-ao.js";const _=JSON.parse('{"title":"Continuous Delivery","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/common2/ci-cd/main/continuous-delivery.md","filePath":"wiki/dev-commit/common2/ci-cd/main/continuous-delivery.md"}'),n={name:"wiki/dev-commit/common2/ci-cd/main/continuous-delivery.md"};function a(r,i,c,s,u,d){return o(),l("div",null,[...i[0]||(i[0]=[t('<h1 id="continuous-delivery" tabindex="-1">Continuous Delivery <a class="header-anchor" href="#continuous-delivery" aria-label="Permalink to &quot;Continuous Delivery&quot;">​</a></h1><ul><li><strong>Continuous Delivery, CD (Непрерывная поставка/доставка)</strong> - подход к разработке программного обеспечения, при котором все изменения, включая новые функции, изменения конфигурации, исправления ошибок и эксперименты — поставляются пользователям максимально быстро и безопасно</li><li>Идея: выполнять CI, плюс автоматически готовить и вести релиз к продакшену. Как правило, в процессе непрерывной доставки требуется выполнять вручную как минимум один этап: одобрить развертывание в продакшен и запустить его</li><li>На протяжении всего процесса непрерывной доставки, мы постоянно получаем обратную связь</li><li>Автоматизируя большинство операций, таких как развертывание, настройки окружения, тестирование, мы сокращаем время поставки новой функциональности</li><li>Позволяет нам доставлять ценность пользователям, небольшими, но частыми партиями. Это позволяет нам как можно скорее получать обратную связь от пользователей, проверять большее количество гипотез и поставлять действительно ценное программное обеспечение</li></ul><h3 id="процесс" tabindex="-1">Процесс <a class="header-anchor" href="#процесс" aria-label="Permalink to &quot;Процесс&quot;">​</a></h3><ol><li>[CI] Разработчик отправляет свои изменения в систему контроля версии</li><li>[CI] На сервере сборки начинается процесс сборки поступивших изменений</li><li>[CI] Запускаются Юнит-тесты</li><li>Собранный пакет, после успешной интеграции, выкладывается на тестовый сервер</li><li>Заинтересованные лица, получают уведомления о выкладке новой версии ПО на тестовую площадку. Начинается вторая фаза тестирования, запускаются интеграционные, ручные, приёмочные, UI тесты</li><li>После успешного прохождения предыдущих шагов, мы имеем готовый к публикации пакет, новой версии ПО</li></ol>',4)])])}const v=e(n,[["render",a]]);export{_ as __pageData,v as default};
